<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/admin_shell.php';security_headers();require_admin();
$db=database();$state=admin_activity_resolution($db);$activity=$state['activity'];
if(!$activity){admin_shell_start('overview','Início',$state);?><section class="admin-empty"><p class="admin-kicker">Nenhuma atividade configurada</p><h2>Crie o primeiro site</h2><p>Configure uma atividade para começar a editar páginas, formulários e mídia.</p><a class="admin-button" href="/admin/activities.php">Configurar atividade</a></section><?php admin_shell_end();exit;}
$id=(int)$activity['id'];cms_pages_seed($db,$id);cms_forms_seed($db,$id);$pages=cms_pages($db,$id);$forms=cms_forms($db,$id);
$q=$db->prepare('SELECT COUNT(*) FROM cms_form_submissions WHERE activity_id=?');$q->execute([$id]);$responses=(int)$q->fetchColumn();
$q=$db->prepare("SELECT COUNT(*) FROM cms_form_submissions WHERE activity_id=? AND status='new'");$q->execute([$id]);$newResponses=(int)$q->fetchColumn();
$q=$db->prepare('SELECT created_at FROM cms_form_submissions WHERE activity_id=? ORDER BY created_at DESC LIMIT 1');$q->execute([$id]);$latestResponse=$q->fetchColumn()?:null;
$assets=$db->query("SELECT kind,COUNT(*) total,MAX(updated_at) latest FROM media_assets WHERE archived_at IS NULL GROUP BY kind")->fetchAll();$media=['image'=>0,'video'=>0];$latestMedia=null;foreach($assets as $asset){$media[$asset['kind']]=(int)$asset['total'];if($asset['latest']&&(!$latestMedia||strtotime($asset['latest'])>strtotime($latestMedia)))$latestMedia=$asset['latest'];}
$mediaErrors=(int)$db->query("SELECT COUNT(*) FROM media_assets WHERE archived_at IS NULL AND processing_status NOT IN ('ready','pending')")->fetchColumn();
$unpublishedPages=count(array_filter($pages,fn(array $p)=>$p['published_revision']===null||(int)$p['draft_revision']!==(int)$p['published_revision']));$unpublishedForms=count(array_filter($forms,fn(array $f)=>$f['published_revision']===null||(int)$f['draft_revision']!==(int)$f['published_revision']));$pending=$unpublishedPages+$unpublishedForms;
$homePt=null;foreach($pages as $page)if(($page['locale']??'')===PUBLIC_LOCALE_PT_BR&&(int)($page['is_home']??0)===1&&($page['status']??'')!=='archived'){$homePt=$page;break;}
function admin_date(?string $date): string{return $date?date('d/m/Y · H:i',strtotime($date)):'Ainda não disponível';}
$publicUrl=admin_public_activity_url($activity);
admin_shell_start('overview','Início',$state);?>
<section class="overview-hero"><div><p class="admin-kicker">Site atual</p><h2><?=h($activity['admin_name'])?></h2><p><?= $pending?'Há trabalho salvo que ainda não está publicado.':'O conteúdo publicado está sincronizado com os rascunhos.' ?></p><p class="public-url"><span>Endereço público</span><a href="<?=h($publicUrl)?>" target="_blank" rel="noopener"><?=h($publicUrl)?></a></p></div><div class="hero-actions"><?php if($homePt):?><a class="admin-button" href="/editor/?page=<?=(int)$homePt['id']?>">Editar página inicial</a><?php else:?><a class="admin-button" href="/admin/pages.php?activity=<?=$id?>">Editar site</a><?php endif;?><a class="admin-button secondary" href="/admin/submissions.php?activity=<?=$id?>">Ver inscrições</a><a class="admin-button secondary" href="<?=h($publicUrl)?>" target="_blank" rel="noopener">Abrir site ↗</a></div></section>
<section class="admin-attention" aria-label="O que precisa de atenção"><article class="admin-attention-card" data-tone="<?=$pending?'attention':'good'?>"><p class="admin-kicker">Publicação</p><strong><?=$pending?$pending.' alteração'.($pending===1?'':'ões').' pendente'.($pending===1?'':'s'):'Tudo publicado'?></strong><p><?=$pending?($unpublishedPages.' página(s) e '.$unpublishedForms.' formulário(s) ainda estão em rascunho.'):'Não há rascunhos diferentes da versão pública.'?></p></article><article class="admin-attention-card" data-tone="<?=$newResponses?'attention':'good'?>"><p class="admin-kicker">Inscrições</p><strong><?=$newResponses?$newResponses.' nova'.($newResponses===1?'':'s'):'Nenhuma nova'?></strong><p><?=$latestResponse?'Última resposta: '.h(admin_date((string)$latestResponse)).'.':'Ainda não houve respostas pelo formulário atual.'?></p></article><article class="admin-attention-card" data-tone="<?=$mediaErrors?'danger':'good'?>"><p class="admin-kicker">Mídia</p><strong><?=$mediaErrors?$mediaErrors.' arquivo'.($mediaErrors===1?'':'s').' com erro':'Processamento normal'?></strong><p><?=$mediaErrors?'Abra a biblioteca para revisar o processamento.':h(admin_media_summary($media['image'],$media['video'])).' disponíveis na biblioteca.'?></p></article></section>
<section class="admin-quick-actions" aria-label="Ações rápidas"><a class="admin-quick-action" href="/admin/pages.php?activity=<?=$id?>"><strong>Páginas</strong><span>Editar conteúdo, criar páginas e publicar.</span></a><a class="admin-quick-action" href="/admin/submissions.php?activity=<?=$id?>"><strong>Respostas</strong><span><?=$responses?> <?= $responses===1?'resposta armazenada':'respostas armazenadas' ?>.</span></a><a class="admin-quick-action" href="/admin/forms.php?activity=<?=$id?>"><strong>Formulário</strong><span>Campos, condições e confirmação após o envio.</span></a><a class="admin-quick-action" href="/admin/media.php?activity=<?=$id?>"><strong>Mídia</strong><span><?=h(admin_media_summary($media['image'],$media['video']))?>.</span></a><a class="admin-quick-action" href="/admin/design.php?activity=<?=$id?>"><strong>Visual</strong><span>Tipografia, cores e aparência geral.</span></a><a class="admin-quick-action" href="/admin/system.php"><strong>Sistema</strong><span>Atualizações, diagnóstico e manutenção.</span></a></section>
<?php admin_shell_end();
